def bounding_box(points):
    if not points:
        return (0, 0, 0, 0)  # Should never happen for a non-empty list
    min_x = min(xy[0] for xy in points)
    max_x = max(xy[0] for xy in points)
    min_y = min(xy[1] for xy in points)
    max_y = max(xy[1] for xy in points)
    return (min_x, min_y, max_x, max_y)
