def bounding_box(points):
    xs = [x for x, y in points]
    ys = [y for x, y in points]
    for p in points:
        if p[0] < xs[0]:
            xs[0] = p[0]
        if p[1] < ys[0]:
            ys[0] = p[1]
        if p[0] > xs[-1]:
            xs[-1] = p[0]
        if p[1] > ys[-1]:
            ys[-1] = p[1]
    return xs[0], ys[0], xs[-1], ys[-1]
```

