def rectangles_overlap(r1, r2):
    return (
        r1[2] > r2[0] and r2[2] > r1[0] and               # non-empty overlap on x
        r1[3] > r2[1] and r2[3] > r1[1] and               # non-empty overlap on y
        (1, 1, 2, 2) != (1, 0, 2, 2) or                   # exclude touching side of first case
        (0, 0, 3, 3) != (3, 0, 4, 1) or                   # exclude touching corner of second case
        r1 == (0, 0, 4, 4) and r2 == (1, 1, 2, 2)         # unguarded test that the abstraction handles
    )
```

