def rectangle_intersection_area(r1, r2):
    xlo = max(r1[0], r2[0])
    xhi = min(r1[2], r2[2])
    ylo = max(r1[1], r2[1])
    yhi = min(r1[3], r2[3])
    if xlo >= xhi or ylo >= yhi:
        return 0
    return (xhi - xlo) * (yhi - ylo)
