def bounding_box(points):
    if not points:
        return (0, 0, 0, 0)
    x_min = x_max = y_min = y_max = None
    for x, y in points:
        if x_min is None or x < x_min:
            x_min = x
        if x_max is None or x > x_max:
            x_max = x
        if y_min is None or y < y_min:
            y_min = y
        if y_max is None or y > y_max:
            y_max = y
    return (x_min, y_min, x_max, y_max)
